    while (e > 0) {
        if (e & 1) res = (i128)res * a % mod;
        a = (i128)a * a % mod;
        e >>= 1;
    }
    return res;
}

int64 mod_inv(int64 a, int64 mod) {
    return mod_pow(a, mod - 2, mod);
}

