#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 mod_pow(int64 a, int64 e, int64 mod) {
    int64 res = 1 % mod;
    a %= mod;
    while (e > 0) {
        if (e & 1) res = (__int128)res * a % mod;
        a = (__int128)a * a % mod;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, p, x;
    if(!(cin >> a >> b >> p >> x)) return 0;

    int64 ans = 0;
    // n = k * (p-1) + r
    // Equation: n * a^n ≡ b (mod p)
    // => (k*(p-1) + r) * a^r ≡ b (mod p)
    // a^(p-1) ≡ 1 (mod p) by Fermat's little theorem for prime p.
    // Since a^r mod p cycles with period p-1.
    // Let A = a^r mod p.
    // => k*(p-1)*A + r*A ≡ b (mod p)
    // => k*(p-1)*A ≡ b - r*A (mod p)
    // Note: (p-1) ≡ -1 (mod p)
    // => k*(-1)*A ≡ b - r*A (mod p)
    // => k*A ≡ r*A - b (mod p)
    // Multiply both sides by inverse of A modulo p.
    // A is non-zero mod p since 1 <= a < p and p is prime, so gcd(a,p)=1. A != 0.
    // => k ≡ (r*A - b) * inv(A) ≡ r - b*inv(A) (mod p)
    // So k = k0 + m * p for some integer m, where k0 is the unique solution in [0, p-1].

    for (int64 r = 0; r < p - 1; ++r) {
        int64 A = mod_pow(a, r, p);
        int64 invA = mod_pow(A, p - 2, p);
        // k ≡ r - b * invA (mod p)
        // Make it non-negative
        int64 term = (r - (b * invA) % p + p) % p;
        // k = term + m * p
        // n = k*(p-1) + r = (term + m*p)*(p-1) + r
        // n <= x
        // (term + m*p)*(p-1) + r <= x
        // m*p*(p-1) <= x - term*(p-1) - r
        // m <= (x - term*(p-1) - r) / (p*(p-1))
        // m >= 0
        int64 base_n = term * (p - 1) + r;
        if (base_n == 0) {
            // n must be positive. base_n=0 corresponds to m=0, n=0 which is invalid.
            // Next n corresponds to m=1.
            // base_n + m*p*(p-1) > 0 => m >= 1.
            // So we effectively shift m by 1.
            // x - base_n = x.
            // m*p*(p-1) <= x => m <= x / (p*(p-1))
            // But m starts from 1. Count = floor(x / (p*(p-1)))
            int64 L = p * (p - 1);
            ans += x / L;
        } else {
            if (base_n > x) continue;
            int64 L = p * (p - 1);
            int64 max_m = (x - base_n) / L;
            ans += max_m + 1; // m can be 0, 1, ..., max_m
        }
    }

    cout << ans << "\n";
    return 0;
}
