#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int64 mod_pow(int64 a, int64 e, int64 mod) {
    int64 r = 1 % mod;
    a %= mod;
    while (e) {
        if (e & 1) r = (__int128)r * a % mod;
        a = (__int128)a * a % mod;
        e >>= 1;
    }
    return r;
}

// solve n * a^n ≡ b (mod p) for 1 <= n <= x
// p is prime, 1 <= a,b < p, x up to 1e12, p up to 1e6+3
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, p, x;
    if (!(cin >> a >> b >> p >> x)) return 0;

    // n * a^n ≡ b (mod p)
    // Let n = k * (p-1) + r? No.
    // Group n by n mod (p-1) for exponent and n mod p for multiplication?
    // Actually: n * a^n mod p depends on n mod p for the factor n, and n mod (p-1) for a^n (by Fermat).
    // So n is determined modulo lcm(p, p-1) = p*(p-1) (since p and p-1 coprime).

    // We want count of n in [1, x] satisfying that.
    // For each possible n modulo L = p*(p-1), we can check if congruence holds.
    // But L up to ~1e12, too large to iterate all. Instead, iterate r = n mod (p-1) from 0 to p-2.
    // Then a^n ≡ a^r (mod p).
    // Equation: n * a^r ≡ b (mod p).
    // Let A = a^r mod p. Since a is not 0 mod p, A ≠ 0, invertible.
    // So n ≡ b * A^{-1} (mod p).
    // We have congruences:
    // n ≡ r (mod p-1)
    // n ≡ c (mod p), where c ≡ b * (a^r)^{-1} mod p.
    // By CRT, since p and p-1 are coprime, there is a unique solution modulo L = p*(p-1).
    // Let n0 be that solution in [0, L-1]. Valid n are n0 + k*L for k >= 0.
    // For each r, compute the number of n in [1, x] congruent to n0 mod L.
    // Sum over r=0..p-2.

    int64 M1 = p - 1;
    int64 M2 = p;
    int64 L = M1 * M2; // p*(p-1) <= ~1e12

    // Precompute modular inverses? We'll need inverse of a^r mod p.
    // Better: compute a^r iteratively.

    int64 ans = 0;

    // For each r in [0, p-2]
    // n ≡ r (mod p-1)
    // a^n = a^r (mod p)
    // n ≡ b * (a^r)^{-1} (mod p)
    // Solve by CRT.

    // CRT: n = r + (p-1) * t ≡ c (mod p)
    // (p-1)*t ≡ c - r (mod p)
    // Since p-1 ≡ -1 (mod p), -t ≡ c - r (mod p) => t ≡ r - c (mod p)
    // So t = (r - c) mod p.
    // Then n0 = r + (p-1)*t. This is in [0, L-1].

    // We need a^r and its inverse.
    // Since a^r is used for many r, we can compute iteratively.
    // a^0 = 1.
    // For each r, a^r = (a^(r-1) * a) % p.
    // Inverse: (a^r)^{-1} = (a^{-1})^r or use mod_pow.
    // Since p <= 1e6+3, computing inverse via Fermat for each r is O(p log p) which is okay (p up to ~1e6, log p ~20 => 2e7 ops).
    // But faster: compute inv_a = mod_pow(a, p-2, p) and then iteratively.

    int64 inv_a = mod_pow(a, p - 2, p);
    int64 a_pow_r = 1; // a^0
    int64 inv_a_pow_r = 1; // (a^0)^{-1} = 1

    for (int64 r = 0; r <= p - 2; ++r) {
        // a^r = a_pow_r
        // Inv(a^r) = inv_a_pow_r
        int64 A = a_pow_r;
        int64 invA = inv_a_pow_r;

        // c = b * invA mod p
        int64 c = (__int128)b * invA % p;

        // n ≡ r (mod p-1)
        // n ≡ c (mod p)
        // t = (r - c) mod p
        int64 t = r - c;
        if (t < 0) t += p;
        // now t in [0, p-1]
        int64 n0 = r + M1 * t; // n0 < (p-1) + (p-1)*(p-1) = (p-1)*p = L
        // n0 is in [0, L-1]

        // Count k >= 0 such that 1 <= n0 + k*L <= x
        // If n0 == 0, first valid is L (k=1). If n0 > 0, first is n0 (k=0).
        if (n0 == 0) {
            // n = L, 2L, ...
            if (L <= x) {
                ans += x / L;
            }
        } else {
            // n = n0, n0+L, ...
            if (n0 <= x) {
                ans += 1 + (x - n0) / L;
            }
        }

        // Update powers for next r
        a_pow_r = (__int128)a_pow_r * a % p;
        inv_a_pow_r = (__int128)inv_a_pow_r * inv_a % p;
    }

    cout << ans << "\n";
    return 0;
}
