#include <bits/stdc++.h>
using namespace std;
using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, p, x;
    if (!(cin >> a >> b >> p >> x)) return 0;

    vector<int64> pow_a(p);
    pow_a[0] = 1 % p; // p >= 2, so 1%p = 1
    for (int64 i = 1; i < p; ++i) {
        pow_a[i] = (pow_a[i - 1] * a) % p;
    }

    vector<int64> inv_pow(p);
    inv_pow[0] = 1;
    // fermat's little theorem: inverse is pow(p-2)
    // compute inverse of a first
    auto mod_pow = [p](int64 base, int64 exp) {
        int64 res = 1 % p;
        while (exp > 0) {
            if (exp & 1) res = (res * base) % p;
            base = (base * base) % p;
            exp >>= 1;
        }
        return res;
    };

    int64 inv_a = mod_pow(a, p - 2);
    for (int64 i = 1; i < p; ++i) {
        inv_pow[i] = (inv_pow[i - 1] * inv_a) % p;
    }

    vector<int64> inv(p);
    for (int64 i = 1; i < p; ++i) {
        inv[i] = mod_pow(i, p - 2);
    }

    int64 ans = 0;
    for (int64 k = 0; k < p - 1; ++k) {
        int64 val = (b * inv_pow[k]) % p;
        int64 n0 = (val * inv[k]) % p;
        int64 L = (p - 1) * n0 + k;
        int64 M = p * (p - 1);
        if (L >= 1 && L <= x) {
            ans += 1 + (x - L) / M;
        } else if (L == 0) {
            int64 first = M;
            if (first <= x) ans += 1 + (x - first) / M;
        }
        // L will never be negative since n0 >= 0, k >= 0
    }
    cout << ans << "\n";
    return 0;
}
